/* @lc app=leetcode id=3325 lang=kotlin */ class Solution { fun numberOfSubstrings(s: String, k: Int): Int = IntArray(26).let { cnt -> s.indices.fold(0 to 0) { (l, ans), r -> (s[r] - 'a').let { c -> cnt.set(c, cnt[c] + 1).let { generateSequence(l) { ll -> if (cnt[c] >= k) cnt.set(s[ll] - 'a', cnt[s[ll] - 'a'] - 1).let { ll + 1 } else null }.last().let { l2 -> l2 to ans + l2 } } } }.second } }